package worktree

import (
	"fmt"
	"regexp"
	"strings"
)

// maxNameLength bounds worktree names; they are used as directory names,
// branch names and session IDs.
const maxNameLength = 100

// validName matches a single path segment of letters, digits, '.', '_' and
// '-' that starts with a letter or digit. Names generated by the web UI
// ("brave-otter-x7k2") always match.
var validName = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

// ValidateName checks that name can be used as a worktree name. The name
// becomes the worktree ID, its directory name (and metadata file name) under
// the worktree root, and the branch beans/<name>, so it must be a single path
// segment and yield a valid git branch name (see git check-ref-format).
func ValidateName(name string) error {
	reason := ""
	switch {
	case name == "":
		reason = "it must not be empty"
	case len(name) > maxNameLength:
		reason = fmt.Sprintf("it must be at most %d characters long", maxNameLength)
	case !validName.MatchString(name):
		reason = "it must start with a letter or digit and contain only letters, digits, '.', '_' and '-'"
	case strings.Contains(name, ".."):
		reason = "it must not contain '..'"
	case strings.HasSuffix(name, "."), strings.HasSuffix(name, ".lock"):
		reason = "it must not end with '.' or '.lock'"
	default:
		return nil
	}
	msg := fmt.Sprintf("invalid worktree name %q: %s", name, reason)
	if s := Slugify(name); s != "" && s != name {
		msg += fmt.Sprintf(" (try %q)", s)
	}
	return fmt.Errorf("%s", msg)
}

var nonSlugChars = regexp.MustCompile(`[^a-z0-9]+`)

// Slugify turns arbitrary text into a valid worktree name ("Run Test" ->
// "run-test"), or returns "" if nothing usable remains.
func Slugify(s string) string {
	s = strings.Trim(nonSlugChars.ReplaceAllString(strings.ToLower(s), "-"), "-")
	if len(s) > maxNameLength {
		s = strings.TrimRight(s[:maxNameLength], "-")
	}
	return s
}
